<template>
  <div class="battle-inline" :class="{ 'battle-inline--spotlight': spotlight }">
    <div class="battle-inline__head">
      <strong>异能战斗演出</strong>
      <div v-if="tags.length" class="battle-inline__tags">
        <span v-for="tag in tags" :key="tag">{{ tag }}</span>
      </div>
    </div>
    <div class="battle-inline__body">{{ body }}</div>
  </div>
</template>

<script setup lang="ts">
declare global {
  interface Window {
    __superpowerBattleProtocol?: string;
  }
}

function resolveProtocolFromDom() {
  const app = document.getElementById('app');
  const mount = app?.parentElement;
  const protocolNode = mount?.previousElementSibling as HTMLElement | null;
  if (protocolNode?.classList.contains('superpower-battle-protocol')) {
    return (protocolNode.textContent ?? '').trim();
  }
  return '';
}

function resolveProtocolFromMessage() {
  try {
    const message = getChatMessages(getCurrentMessageId())?.[0]?.message ?? '';
    const matches = Array.from(message.matchAll(/<战斗演出>\s*([\s\S]*?)<\/战斗演出>/gsi));
    return (matches.at(-1)?.[1] ?? '').trim();
  } catch {
    return '';
  }
}

function normalizeProtocol(input: string) {
  const text = input
    .replace(/<think>[\s\S]*?<\/think>/gsi, '')
    .replace(/<thinking>[\s\S]*?<\/thinking>/gsi, '')
    .trim();
  if (!text) return '';

  const matches = Array.from(text.matchAll(/<战斗演出>\s*([\s\S]*?)<\/战斗演出>/gsi));
  const fromTaggedBlock = (matches.at(-1)?.[1] ?? '').trim();
  if (fromTaggedBlock) return fromTaggedBlock;

  return text;
}

const raw = computed(() => {
  const fromWindow = normalizeProtocol(window.__superpowerBattleProtocol ?? '');
  if (fromWindow) return fromWindow;
  const fromDom = normalizeProtocol(resolveProtocolFromDom());
  if (fromDom) return fromDom;
  return normalizeProtocol(resolveProtocolFromMessage());
});

const parsed = computed(() => {
  const lines = raw.value
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);

  const tagLine = lines.find(line => line.startsWith('标签:'));
  const tags = (tagLine ? tagLine.replace(/^标签:\s*/, '') : '')
    .split(/[，,]/)
    .map(item => item.trim())
    .filter(Boolean);

  const contentLines = lines.filter(line => !line.startsWith('标签:') && !line.startsWith('内容:'));
  const directContent = lines.find(line => line.startsWith('内容:'))?.replace(/^内容:\s*/, '') ?? '';
  const body = [directContent, ...contentLines].filter(Boolean).join('\n');

  return {
    tags,
    body: body || raw.value || '无战斗内容',
  };
});

const spotlightKeywords = ['技能释放', '异能爆发', '召唤武器', '怪物异化', '特殊处决', '特殊处决'];

const tags = computed(() => parsed.value.tags);
const spotlight = computed(() => tags.value.some(tag => spotlightKeywords.some(keyword => tag.includes(keyword))));
const body = computed(() => parsed.value.body);
</script>

